1	import React, { createContext, useContext, useState, useEffect } from 'react';
2	import { getEmpresas, getPlataformaConfig } from '../services/adminService';
3	import { useAuth } from './AuthContext';
4	
5	const LocalModeContext = createContext(null);
6	
7	// Modo individual (mono-estabelecimento) restringe o admin a 1 restaurante.
8	// Duas fontes possíveis: VITE_LOCAL_RESTAURANT_ID no .env (override fixo de build,
9	// self-hosted) ou o checkbox "Instalação individual" em Admin > Configurações
10	// (salvo no banco, ajustável sem rebuild). O .env, quando definido, tem prioridade.
11	const ENV_LOCAL_ID = import.meta.env.VITE_LOCAL_RESTAURANT_ID
12	  ? parseInt(import.meta.env.VITE_LOCAL_RESTAURANT_ID, 10)
13	  : null;
14	
15	export const LocalModeProvider = ({ children }) => {
16	  const { loading, userProfile } = useAuth() ?? {};
17	  const [dbLocalId, setDbLocalId] = useState(null);
18	  const [restauranteNome, setRestauranteNome] = useState(null);
19	
20	  const localId = ENV_LOCAL_ID ?? dbLocalId;
21	
22	  useEffect(() => {
23	    if (ENV_LOCAL_ID) return; // .env já resolve, não precisa consultar o banco
24	    if (loading || userProfile?.role !== 'admin') return;
25	    getPlataformaConfig()
26	      .then((cfg) => {
27	        if (cfg.modo_individual && cfg.modo_individual_restaurant_id) {
28	          setDbLocalId(cfg.modo_individual_restaurant_id);
29	        } else {
30	          setDbLocalId(null);
31	        }
32	      })
33	      .catch(() => {});
34	  }, [loading, userProfile?.role]);
35	
36	  useEffect(() => {
37	    if (!localId) return;
38	    getEmpresas()
39	      .then((d) => {
40	        const found = (d.empresas ?? []).find((e) => e.id === localId);
41	        if (found) setRestauranteNome(found.name);
42	      })
43	      .catch(() => {});
44	  }, [localId]);
45	
46	  return (
47	    <LocalModeContext.Provider value={{ isLocalMode: !!localId, localRestaurantId: localId, restauranteNome }}>
48	      {children}
49	    </LocalModeContext.Provider>
50	  );
51	};
52	
53	export const useLocalMode = () => useContext(LocalModeContext);
54	
55	// Banner reutilizável para todas as páginas admin
56	export const LocalModeBanner = () => {
57	  const { isLocalMode, restauranteNome, localRestaurantId } = useLocalMode() ?? {};
58	  if (!isLocalMode) return null;
59	  return (
60	    <div className="bg-amber-50 dark:bg-amber-950/30 border-b border-amber-300 dark:border-amber-900 px-6 py-2 flex items-center gap-2 text-amber-800 dark:text-amber-300 text-xs font-semibold">
61	      <span className="w-2 h-2 rounded-full bg-amber-500 animate-pulse flex-shrink-0" />
