269	  // faturado, e devolve o status atual de bloqueio da loja.
270	  // forcar=true também gera fatura do período atual mesmo que ainda não tenha
271	  // fechado (usado pelo botão "Renovar agora"/"Gerar fatura" sob demanda).
272	  async sincronizarPeriodo(restaurantId: number, forcar = false) {
