281	
282	    // Marca vencidas
283	    await this.supabase.client
284	      .from('plano_faturas')
285	      .update({ status: 'vencida', atualizado_em: agora.toISOString() })
286	      .eq('assinatura_id', assinatura.id)
287	      .eq('status', 'pendente')
288	      .lt('vencimento', agora.toISOString());
289	
290	    // Gera períodos fechados pendentes de fatura (+ o período atual se forcar=true)
291	    let inicioPeriodo = assinatura.ultimo_periodo_faturado_fim
292	      ? new Date(assinatura.ultimo_periodo_faturado_fim)
293	      : new Date(assinatura.data_inicio);
294	    let ultimoFimFaturado = assinatura.ultimo_periodo_faturado_fim
295	      ? new Date(assinatura.ultimo_periodo_faturado_fim)
296	      : null;
297	
298	    // Se já existe fatura pendente/vencida de QUALQUER período, "Renovar agora"
299	    // não pode gerar outra — o dono tem que pagar a que já existe primeiro.
300	    let temPendenteAberta = false;
301	    if (forcar) {
302	      const { data: pendenteExistente, error: pendErroCheck } = await this.supabase.client
303	        .from('plano_faturas')
304	        .select('id')
305	        .eq('assinatura_id', assinatura.id)
306	        .in('status', ['pendente', 'vencida'])
307	        .limit(1)
308	        .maybeSingle();
309	      if (pendErroCheck) throw pendErroCheck;
310	      temPendenteAberta = !!pendenteExistente;
311	    }
312	
313	    // eslint-disable-next-line no-constant-condition
314	    while (true) {
315	      const fimPeriodo = somarMeses(inicioPeriodo, meses);
316	      const periodoFechado = fimPeriodo < agora;
317	      if (!periodoFechado && !forcar) break;
318	
319	      if (!periodoFechado) {
320	        if (temPendenteAberta) break;
321	
322	        // Período em aberto forçado: se já existe fatura pra esse período (de um
323	        // "Renovar agora" anterior), não gera outra nem avança o ciclo de novo —
324	        // senão cada clique empurraria a cobrança um mês pra frente.
325	        const { data: jaExiste, error: existeErro } = await this.supabase.client
326	          .from('plano_faturas')
327	          .select('id')
328	          .eq('assinatura_id', assinatura.id)
329	          .eq('periodo_inicio', inicioPeriodo.toISOString())
330	          .maybeSingle();
331	        if (existeErro) throw existeErro;
332	        if (jaExiste) break;
333	      }
334	
335	      const { data: faturamentoRows, error: fatErro } = await this.supabase.client
336	        .from('orders')
337	        .select('total')
338	        .eq('restaurant_id', restaurantId)
339	        .eq('status', 'delivered')
340	        .gte('created_at', inicioPeriodo.toISOString())
341	        .lt('created_at', fimPeriodo.toISOString());
342	      if (fatErro) throw fatErro;
343	
344	      const faturamento = (faturamentoRows ?? []).reduce((acc, o: any) => acc + (o.total ?? 0), 0);
345	
346	      const isento = plano.piso_faturamento != null && faturamento < plano.piso_faturamento;
347	      const valorFatura = isento ? 0 : plano.valor;
348	      const vencimento = somarDias(fimPeriodo, 5);
349	
350	      const { error: insErro } = await this.supabase.client
351	        .from('plano_faturas')
352	        .insert({
353	          assinatura_id: assinatura.id,
354	          restaurant_id: restaurantId,
355	          periodo_inicio: inicioPeriodo.toISOString(),
356	          periodo_fim: fimPeriodo.toISOString(),
357	          valor: valorFatura,
358	          status: isento ? 'isenta' : 'pendente',
359	          vencimento: vencimento.toISOString(),
360	        });
361	      // Ignora conflito de unicidade (fatura já gerada em corrida concorrente)
362	      if (insErro && !String(insErro.message).includes('duplicate')) throw insErro;
363	
364	      ultimoFimFaturado = fimPeriodo;
365	      inicioPeriodo = fimPeriodo;
366	
367	      if (!periodoFechado) break; // gerou o período em aberto sob demanda — não continua pro futuro
368	    }
369	
370	    if (ultimoFimFaturado && ultimoFimFaturado.getTime() !== new Date(assinatura.ultimo_periodo_faturado_fim ?? 0).getTime()) {
371	      await this.supabase.client
372	        .from('assinaturas')
373	        .update({ ultimo_periodo_faturado_fim: ultimoFimFaturado.toISOString(), updated_at: agora.toISOString() })
374	        .eq('id', assinatura.id);
375	    }
376	
377	    // Recalcula bloqueio com base no estado atual das faturas
378	    const tolerancia = await this.diasTolerancia();
379	    const { data: pendentes, error: pendErro } = await this.supabase.client
380	      .from('plano_faturas')
381	      .select('id, vencimento, status')
382	      .eq('assinatura_id', assinatura.id)
383	      .in('status', ['pendente', 'vencida'])
384	      .order('vencimento', { ascending: true });
385	    if (pendErro) throw pendErro;
386	
387	    let bloqueado = false;
388	    let diasAtraso = 0;
389	    let faturaPendenteId: number | null = null;
390	    if ((pendentes ?? []).length > 0) {
391	      faturaPendenteId = pendentes[0].id;
392	      const vencimento = new Date(pendentes[0].vencimento);
393	      diasAtraso = Math.max(0, Math.floor((agora.getTime() - vencimento.getTime()) / 86400000));
394	      bloqueado = diasAtraso > tolerancia;
395	    }
396	
397	    const proximaCobranca = somarMeses(ultimoFimFaturado ?? inicioPeriodo, meses);
398	
399	    return {
400	      bloqueado,
401	      dias_atraso: diasAtraso,
402	      fatura_pendente_id: faturaPendenteId,
403	      plano_nome: plano.nome,
404	      proxima_cobranca: proximaCobranca.toISOString(),
405	    };
406	  }
