478	  // ── Pagamento via PagBank (cobrança direta loja -> plataforma, sem split) ──
479	
480	  private async clientPlataforma() {
481	    const { data: platData } = await this.supabase.client
482	      .from('platform_settings').select('config').eq('id', 1).maybeSingle();
483	    const platCfg = (platData?.config ?? {}) as Record<string, any>;
484	
485	    const token = platCfg.pagbank_platform_token || this.config.get<string>('PAGBANK_PLATFORM_TOKEN') || '';
486	    if (!token) throw new BadRequestException('PagBank da plataforma não configurado — fale com o suporte');
487	    const sandbox = platCfg.pagbank_sandbox ?? (this.config.get('PAGBANK_SANDBOX') !== 'false');
488	
489	    const baseWebhook =
490	      platCfg.pagbank_webhook_url ||
491	      this.config.get<string>('PAGBANK_WEBHOOK_URL') ||
492	      'http://localhost:3002/pagamentos/webhook';
493	    const webhookUrl = baseWebhook.replace('/pagamentos/webhook', '/planos/webhook');
