509	  async pagarFatura(
510	    restaurantId: number,
511	    faturaId: number,
512	    body: { nome: string; email: string; cpf_cnpj: string; metodo?: 'pix' | 'credit_card' | 'debit_card'; card_encrypted?: string; parcelas?: number },
513	  ) {
514	    const fatura = await this.buscarFaturaDoRestaurante(restaurantId, faturaId);
515	    if (fatura.status === 'paga') throw new BadRequestException('Fatura já está paga');
516	    if (fatura.status === 'isenta' || fatura.status === 'cancelada') {
517	      throw new BadRequestException('Esta fatura não pode ser paga');
518	    }
519	
520	    const metodo = body.metodo ?? 'pix';
521	    if (metodo === 'credit_card' || metodo === 'debit_card') {
522	      return this.pagarFaturaCartao(fatura, body, metodo);
523	    }
524	
525	    // Reaproveita o QR já gerado pra essa fatura em vez de abrir ordem nova a cada clique
526	    if (fatura.pix_code && fatura.pagbank_order_id) {
527	      return { pix_code: fatura.pix_code, pix_qr_url: fatura.pix_qr_url, fatura_id: fatura.id };
528	    }
529	
530	    const { client, webhookUrl } = await this.clientPlataforma();
531	
532	    const valorCentavos = Math.round(fatura.valor * 100);
533	    const refId = `PLANO_${fatura.id}_${Date.now()}`;
534	
535	    let resposta: any;
536	    try {
537	      resposta = await client.criarOrdemPix({
538	        reference_id: refId,
539	        valor_centavos: valorCentavos,
540	        customer: {
541	          name: body.nome,
542	          email: body.email,
543	          tax_id: body.cpf_cnpj.replace(/\D/g, ''),
544	        },
545	        itens: [{ name: `Assinatura — fatura #${fatura.id}`, quantity: 1, unit_amount: valorCentavos }],
546	        webhook_url: webhookUrl,
547	      });
548	    } catch (e: any) {
549	      throw new BadRequestException(e?.message ?? 'Falha ao gerar cobrança no PagBank');
550	    }
551	
552	    const qrCode = resposta?.qr_codes?.[0];
553	    const pixCode = qrCode?.text ?? null;
554	    const pixQrUrl = qrCode?.links?.find((l: any) => l.media === 'image/png')?.href ?? null;
555	
556	    const { error } = await this.supabase.client
557	      .from('plano_faturas')
558	      .update({
559	        pagbank_order_id: resposta.id,
560	        reference_id: refId,
561	        pix_code: pixCode,
562	        pix_qr_url: pixQrUrl,
563	        atualizado_em: new Date().toISOString(),
564	      })
565	      .eq('id', fatura.id);
566	    if (error) throw error;
567	
568	    return { pix_code: pixCode, pix_qr_url: pixQrUrl, fatura_id: fatura.id };
569	  }
