571	  // Cartão confirma na hora (sem espera de webhook) — diferente do Pix
572	  private async pagarFaturaCartao(
573	    fatura: any,
574	    body: { nome: string; email: string; cpf_cnpj: string; card_encrypted?: string; parcelas?: number },
575	    metodo: 'credit_card' | 'debit_card',
576	  ) {
577	    if (!body.card_encrypted) throw new BadRequestException('Dados do cartão ausentes');
578	
579	    const { client, webhookUrl } = await this.clientPlataforma();
580	    const valorCentavos = Math.round(fatura.valor * 100);
581	    const refId = `PLANO_${fatura.id}_${Date.now()}`;
582	
583	    let resposta: any;
584	    try {
585	      resposta = await client.criarOrdemCartao({
586	        reference_id: refId,
587	        valor_centavos: valorCentavos,
588	        customer: {
589	          name: body.nome,
590	          email: body.email,
591	          tax_id: body.cpf_cnpj.replace(/\D/g, ''),
592	        },
593	        itens: [{ name: `Assinatura — fatura #${fatura.id}`, quantity: 1, unit_amount: valorCentavos }],
594	        card_encrypted: body.card_encrypted,
595	        parcelas: metodo === 'credit_card' ? (body.parcelas ?? 1) : 1,
596	        tipo: metodo === 'credit_card' ? 'CREDIT_CARD' : 'DEBIT_CARD',
597	        webhook_url: webhookUrl,
598	      });
599	    } catch (e: any) {
600	      throw new BadRequestException(e?.message ?? 'Falha ao processar cartão no PagBank');
601	    }
602	
603	    const charge = resposta?.charges?.[0];
604	    const pago = STATUS_PAGOS.includes(charge?.status);
605	
606	    const { error } = await this.supabase.client
607	      .from('plano_faturas')
608	      .update({
609	        pagbank_order_id: resposta.id,
610	        reference_id: refId,
611	        status: pago ? 'paga' : fatura.status,
612	        pago_em: pago ? new Date().toISOString() : null,
613	        atualizado_em: new Date().toISOString(),
614	      })
615	      .eq('id', fatura.id);
616	    if (error) throw error;
617	
618	    if (!pago) {
619	      throw new BadRequestException(charge?.status === 'DECLINED' ? 'Cartão recusado' : 'Pagamento não aprovado, tente novamente');
620	    }
621	
622	    return { pago: true, fatura_id: fatura.id };
623	  }
