625	  async processarWebhook(evento: any) {
626	    const payload = evento?.data ?? evento;
627	    const pagbankOrderId: string = payload?.id ?? payload?.reference_id;
628	    const charges: any[] = payload?.charges ?? [];
629	    const payments: any[] = payload?.payments ?? [];
630	
631	    const detalhe = charges[0] ?? payments[0];
632	    if (!detalhe) return { ignorado: true };
633	
634	    const statusPagbank: string = detalhe?.status ?? payload?.status ?? '';
635	    if (!STATUS_PAGOS.includes(statusPagbank)) return { ignorado: true };
636	
637	    const { data: fatura } = await this.supabase.client
638	      .from('plano_faturas')
639	      .select('id, status')
640	      .eq('pagbank_order_id', pagbankOrderId)
641	      .maybeSingle();
642	
643	    if (!fatura) return { ignorado: true, motivo: 'fatura não encontrada' };
644	    if (fatura.status === 'paga') return { ignorado: true, motivo: 'já processado' };
645	
646	    await this.supabase.client
647	      .from('plano_faturas')
648	      .update({ status: 'paga', pago_em: new Date().toISOString(), atualizado_em: new Date().toISOString() })
649	      .eq('id', fatura.id);
650	
651	    return { processado: true, fatura_id: fatura.id };
652	  }
