497	                        className="px-2.5 py-1 text-xs font-semibold text-blue-700 dark:text-blue-400 hover:bg-blue-50 dark:hover:bg-blue-950/40 rounded-lg disabled:opacity-40"
498	                      >
499	                        {assinatura ? 'Trocar' : 'Atribuir'}
500	                      </button>
501	                      {assinatura && assinatura.status !== 'cancelada' && (
502	                        <>
503	                          <button
504	                            onClick={() => handleGerarFatura(emp.id)}
505	                            disabled={processando === emp.id}
